const METHODEN = ["readback", "provider_receipt", "provider_status", "none"];
const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const ergebnis = [];

for (const item of $input.all()) {
  const kontext = item.json.context_id;
  const methode = item.json.verification_method;
  const readbackMoeglich = item.json.readback_supported === true;
  const beobachtet = item.json.observed || {};
  const erwartet = item.json.expected || {};

  if (KONTEXTE.indexOf(kontext) === -1) {
    throw new Error("evidence_verify_invalid_input: context_id nicht im Register");
  }
  if (METHODEN.indexOf(methode) === -1) {
    throw new Error("evidence_verify_invalid_input: verification_method unzulaessig");
  }
  if (!item.json.action_id) {
    throw new Error("evidence_verify_invalid_input: action_id fehlt");
  }

  let bestanden = false;
  let grund = "";
  let ergebniswert = "failed";

  if (readbackMoeglich && methode !== "readback") {
    grund = "readback_required: Ein unabhaengiger Readback ist moeglich und damit verpflichtend (D3).";
  } else if (methode === "none") {
    grund = "no_verification: Ohne Nachweis gilt die Aktion nicht als erfolgreich.";
  } else {
    const schluessel = Object.keys(erwartet);
    let abweichung = "";
    for (const k of schluessel) {
      if (JSON.stringify(beobachtet[k]) !== JSON.stringify(erwartet[k])) {
        abweichung = k;
        break;
      }
    }
    if (schluessel.length === 0) {
      grund = "expected_empty: Ohne erwarteten Zielzustand ist kein Abgleich moeglich.";
    } else if (abweichung) {
      grund = "mismatch: Feld " + abweichung + " weicht vom erwarteten Zustand ab.";
    } else {
      bestanden = true;
      ergebniswert = "verified";
      grund = "";
    }
  }

  ergebnis.push({ json: {
    verification_passed: bestanden,
    verification_result: ergebniswert,
    verification_method: methode,
    readback_supported: readbackMoeglich,
    reason: grund,
    action_id: item.json.action_id,
    contract_tool_id: item.json.contract_tool_id || null,
    contract_version: item.json.contract_version || null,
    context_id: kontext,
    observed_at: new Date().toISOString(),
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;
